import React from 'react';
import styles from './FriendsList.module.scss';

const friends = [
  { name: 'Eddie Lobanovskiy', email: 'laboanovskiy@gmail.com' },
  { name: 'Alexey Stave', email: 'alexey.stave@gmail.com' },
  { name: 'Anton Tkacheve', email: 'anton.tkacheve@gmail.com' },
  { name: 'Eddie Lobanovskiy', email: 'laboanovskiy@gmail.com' },
  { name: 'Alexey Stave', email: 'alexey.stave@gmail.com' },
  { name: 'Anton Tkacheve', email: 'anton.tkacheve@gmail.com' },
];

export default function FriendsList() {
  return (
    <div className={styles.friendsList}>
      <h2 className={styles.heading}>Friends</h2>
      <div className={styles.friendsContainer}>
        {friends.map((friend, index) => (
          <div key={index} className={styles.friendItem}>
            <img
              src="https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=50&h=50&fit=crop"
              alt={friend.name}
              className={styles.friendAvatar}
            />
            <div className={styles.friendInfo}>
              <span className={styles.friendName}>{friend.name}</span>
              <span className={styles.friendEmail}>{friend.email}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
